#!/usr/bin/env bash
# Documentation : partie « Authentification et droits » en dix chapitres (remplace auth/authentification.mdx).
# Prérequis : apply-fix-auth.sh. Aucune migration.
# Usage (racine du repo) : bash apply-docs-auth.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/auth/vue-d-ensemble.mdx" 2>/dev/null | grep -qF "La vue d’ensemble, et les pièges"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "TOO_MANY_ATTEMPTS" "apps/web/src/features/auth/errors/auth.errors.ts" 2>/dev/null || { echo "❌ lancer d'abord apply-fix-auth.sh"; exit 1; }
MODIFIED=()
EXPECT=()
DIFF=0; for e in "${EXPECT[@]}"; do h=${e%%:*}; f=${e#*:}; c=$(git rev-parse "HEAD:$f" 2>/dev/null | cut -c1-12); if [ "$c" != "$h" ]; then [ $DIFF = 0 ] && echo "❌ ces fichiers ne sont pas dans l'état attendu (rien n'a été touché) :"; echo "   $f"; DIFF=1; fi; done; [ $DIFF = 0 ] || exit 1
CREATED=("apps/web/content/docs/dev/auth/fermer-une-session.mdx" "apps/web/content/docs/dev/auth/la-session-dans-le-backend.mdx" "apps/web/content/docs/dev/auth/le-modele-et-le-contrat.mdx" "apps/web/content/docs/dev/auth/le-mot-de-passe-oublie.mdx" "apps/web/content/docs/dev/auth/le-navigateur-et-le-proxy.mdx" "apps/web/content/docs/dev/auth/les-droits-par-les-groupes.mdx" "apps/web/content/docs/dev/auth/lire-la-session.mdx" "apps/web/content/docs/dev/auth/pourquoi-une-chaine.mdx" "apps/web/content/docs/dev/auth/se-connecter.mdx" "apps/web/content/docs/dev/auth/vue-d-ensemble.mdx")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "La vue d’ensemble, et les pièges" "apps/web/content/docs/dev/auth/vue-d-ensemble.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

mkdir -p "apps/web/content/docs/dev/auth"
base64 -d > "apps/web/content/docs/dev/auth/fermer-une-session.mdx" <<'B64'
