B64

python3 - <<'PY'
import base64
spec_skip_done = False
def sub(path, old, new):
    old, new = base64.b64decode(old).decode(), base64.b64decode(new).decode()
    s = open(path, encoding="utf-8").read()
    if s.count(old) == 0 and s.count(new) == 1 and spec_skip_done: return  # déjà fait par un script précédent
    assert s.count(old) == 1, (path, old[:80], s.count(old))
    open(path, "w", encoding="utf-8").write(s.replace(old, new))
print("  édits ok (0 substitutions, 10 fichiers créés, 0 remplacés)")
PY
trap - ERR

# Table de l'index : ligne « Authentification et droits », quel que soit son texte actuel.
F=apps/web/content/docs/dev/index.mdx
if ! git diff --quiet HEAD -- "$F"; then echo "❌ $F a des modifications non commitées"; restore; exit 1; fi
MODIFIED+=("$F")
python3 - "$F" <<'PY2'
import re, sys
p = sys.argv[1]; s = open(p, encoding="utf-8").read()
new = "[\"Authentification et droits\",\"En dix chapitres : la chaîne et ses mécanismes, le modèle de session et son contrat, la connexion, la lecture de la session à chaque requête, la session dans le backend, sa fin, le mot de passe oublié, le navigateur et le proxy, les droits par les groupes, la vue d’ensemble et les pièges.\",\"rédigée\"]"
s2, n = re.subn(r'\["Authentification et droits","[^"]*","[^"]*"\]', lambda m: new, s)
assert n == 1, n
open(p, "w", encoding="utf-8").write(s2)
PY2
OLDF=apps/web/content/docs/dev/auth/authentification.mdx
if git cat-file -e "HEAD:$OLDF" 2>/dev/null; then rm -f "$OLDF"; MODIFIED+=("$OLDF"); fi
[ "${AKFC_APPLY_ONLY:-0}" = "1" ] && { echo "Appliqué (sans vérification ni commit)."; exit 0; }
echo "== pnpm check =="
if pgrep -f "next dev" >/dev/null 2>&1; then
  echo "  (pnpm dev tourne : vérification sans effacer .next)"
  CHECK="node scripts/check-next-conventions.mjs && node scripts/check-tour-targets.mjs && pnpm --filter backend typecheck && pnpm typecheck && pnpm lint"
else
  CHECK="pnpm check"
fi
if ! bash -c "$CHECK" > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"
  grep -nE "error TS|✗ tutos|ERR_|Error:|EACCES|Permission denied" /tmp/akfc_tc.log | head -12
  echo "  … fin du journal :"; grep -v '^[[:space:]]*$' /tmp/akfc_tc.log | tail -15
  restore; exit 1
fi
echo "  ✅ check OK"
git add -- "${MODIFIED[@]}" "${CREATED[@]}"
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
docs: partie « Authentification et droits » en 10 chapitres — profondeur du tutoriel d'origine restaurée

- pourquoi une chaîne, le modèle et le contrat, se connecter (casse des adresses, limite d'essais),
  lire la session, la session dans le backend, fermer une session, mot de passe oublié,
  navigateur et proxy, droits par les groupes, vue d'ensemble (histoires, pièges, reste à faire)
- remplace auth/authentification.mdx ; ligne de l'index mise à jour

